import {it,expect} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {newId} from '../src/domain/model';
import type {ProjectData} from '../src/domain/types';
import {bootstrapNativeProject,type AtomicSyncRepository,type ServerIdentity} from '../src/sync/server';
import {applyEditorOperation,readEditorImage} from '../src/sync/editor';
import {createSyncOperation,type SyncOperation} from '../src/sync/protocol';
import {assertAck} from '../src/sync/validation';
const root='/tmp/shinariokanri-independent-rb09-ff971b7/independent',container='shinariokanri-independent-rb09-ff971b7',owner:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000001',sessionId:'10000000-0000-4000-8000-000000000001'},editor:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000002',sessionId:'10000000-0000-4000-8000-000000000002'},calls:unknown[]=[];
function arg(v:unknown):string{if(v===null)return'null';if(v&&typeof v==='object'&&'rawSQL'in v)return(v as {rawSQL:string}).rawSQL;return"'"+(typeof v==='object'?JSON.stringify(v):String(v)).replace(/'/g,"''")+"'"+(typeof v==='object'?'::jsonb':'');}
function sql(text:string){const r=spawnSync('docker',['exec','-i',container,'psql','-U','postgres','-qAt','-v','ON_ERROR_STOP=1'],{input:text,encoding:'utf8',timeout:20000,maxBuffer:32*1024*1024});calls.push({sql:text,status:r.status,stdout:r.stdout,stderr:r.stderr});writeFileSync(root+'/sql-editor-calls.json',JSON.stringify(calls,null,2)+'\n');if(r.status!==0)throw Error(r.stderr||'SQL_CALL_FAILED');return r.stdout;}
function rpc(name:string,values:unknown[]){const out=sql('set role service_role;\nselect public.'+name+'('+values.map(arg).join(',')+')::text;\n').trim();return out?JSON.parse(out):null;}
const repository:AtomicSyncRepository={read:async(i,p,b,o)=>rpc('scenario_sync_engine_context',[i.accountId,i.sessionId,p,b,o]),bootstrap:async(i,v)=>rpc('scenario_sync_bootstrap',[i.accountId,i.sessionId,v.project.projectId,v.project,v.documents,v.worlds]),commit:async(i,v)=>rpc('scenario_sync_commit_prepared',[i.accountId,i.sessionId,v.projectId,v.expectedRevision,v.operation,v.operationHash,v.ack,v.documents,v.image,{rawSQL:'ARRAY['+(v.derivedIds??[]).map(id=>"'"+id+"'").join(',')+']::uuid[]'}])};
function proof(id:string,data:unknown){writeFileSync(root+'/fixtures/'+id+'.json',JSON.stringify(data,null,2)+'\n');}
async function seed(){const f=JSON.parse(readFileSync(root+'/fixtures/native-two-targets.json','utf8')) as {p:ProjectData;idA:string;idB:string};f.p.projectId=newId();f.p.entities.forEach(e=>e.projectId=f.p.projectId);const a=f.p.entities.find(e=>e.id===f.idA)!;a.customValues['private-editor-canary']='PRIVATE_GRANTED_DOC_FIELD';const b=f.p.entities.find(e=>e.id===f.idB)!;b.visibility='private';b.name='PRIVATE_EDITOR_RECORD_CANARY';await bootstrapNativeProject(repository,owner,{project:f.p,worlds:{}});rpc('scenario_membership',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,'editor',null,false,{rawSQL:'array[]::uuid[]'},0]);rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:f.idA,fields:['name']}],1,1]);return f;}
async function rename(f:Awaited<ReturnType<typeof seed>>,name='許可された編集😀'):Promise<SyncOperation>{const image=await readEditorImage(repository,editor,f.p.projectId),base=image.documents[0],local=structuredClone(base);local.fields.name=name;return createSyncOperation({scope:{accountId:editor.accountId,projectId:f.p.projectId},baseRevision:image.serverRevision,operationId:newId(),targets:[{base,local}]});}
it('R9ESV01 fieldset RPC→typed editor apply→duplicate ACK keeps private canonical fields only in the internal engine and returns a valid scoped receipt',async()=>{const f=await seed(),read=await readEditorImage(repository,editor,f.p.projectId);expect(read.documents).toHaveLength(1);expect(Object.keys(read.documents[0].fields).sort()).toEqual(['createdAt','kind','name','visibility']);expect(JSON.stringify(read)).not.toMatch(/PRIVATE_|customValues|data.body/);expect(JSON.stringify(read)).not.toContain(f.idB);const op=await rename(f),ack=await applyEditorOperation(repository,editor,op);await assertAck(op,ack);expect(ack.status).toBe('applied');expect(await applyEditorOperation(repository,editor,op)).toEqual(ack);expect(JSON.stringify(ack)).not.toMatch(/PRIVATE_|customValues|data.body/);const after=await repository.read(owner,f.p.projectId,null,null);expect(after.nativeImage.entities.find(e=>e.id===f.idA)?.customValues['private-editor-canary']).toBe('PRIVATE_GRANTED_DOC_FIELD');expect(after.nativeImage.entities.find(e=>e.id===f.idB)?.name).toBe('PRIVATE_EDITOR_RECORD_CANARY');proof('R9ESV01',{read,op,ack,privateFieldsStillPresentInOwnerEngine:true,afterRevision:after.serverRevision});});
it('R9ESV02 one forbidden private ID in an otherwise valid batch refuses every editor update and operation evidence',async()=>{const f=await seed(),wire=await rename(f,'採用してはいけない名前'),ownerState=await repository.read(owner,f.p.projectId,'1',null),privateBase=ownerState.documents.find(d=>d.id===f.idB)!,privateLocal=structuredClone(privateBase);privateLocal.fields.name='禁止更新';const op=await createSyncOperation({...wire,targets:[{base:wire.targets[0].base,local:wire.targets[0].local},{base:privateBase,local:privateLocal}]});await expect(applyEditorOperation(repository,editor,op)).rejects.toMatchObject({code:'FORBIDDEN'});const after=await repository.read(owner,f.p.projectId,null,op.operationId);expect(after.serverRevision).toBe('1');expect(after.documents).toEqual(ownerState.documents);expect(after.previousAck).toBe(null);proof('R9ESV02',{operation:op,after,entireBatchRefused:true});});
it('R9ESV03 scope revocation after typed validation is enforced again under the locked SQL commit',async()=>{const f=await seed(),op=await rename(f,'撤回後に更新してはいけない'),before=await repository.read(owner,f.p.projectId,null,null),guarded:AtomicSyncRepository={...repository,commit:async(i,v)=>{sql("update scenario_private.editor_scopes set revoked_at=now() where project_id='"+f.p.projectId+"' and account_id='"+editor.accountId+"';");return repository.commit(i,v);}};await expect(applyEditorOperation(guarded,editor,op)).rejects.toThrow('FORBIDDEN');const after=await repository.read(owner,f.p.projectId,null,op.operationId);expect(after.documents).toEqual(before.documents);expect(after.serverRevision).toBe('1');expect(after.previousAck).toBe(null);proof('R9ESV03',{operation:op,after,lockedScopeRefusal:true});});
it('R9ESV04 stale membership approval and direct authenticated access to the canonical engine RPC are both refused',async()=>{const f=await seed(),first=rpc('scenario_project_members',[owner.accountId,owner.sessionId,f.p.projectId]);expect(first.membershipRevision).toBe('2');rpc('scenario_membership',[owner.accountId,owner.sessionId,f.p.projectId,'00000000-0000-4000-8000-000000000003','reader',null,false,{rawSQL:'array[]::uuid[]'},2]);expect(()=>rpc('scenario_membership',[owner.accountId,owner.sessionId,f.p.projectId,'00000000-0000-4000-8000-000000000003','owner',null,false,{rawSQL:'array[]::uuid[]'},2])).toThrow('REVISION_CHANGED');expect(()=>sql('set role authenticated;\nselect public.scenario_sync_engine_context('+[editor.accountId,editor.sessionId,f.p.projectId,null,null].map(arg).join(',')+');')).toThrow('permission denied');const after=rpc('scenario_project_members',[owner.accountId,owner.sessionId,f.p.projectId]);expect(after.members.find((m:{accountId:string})=>m.accountId==='00000000-0000-4000-8000-000000000003').role).toBe('reader');proof('R9ESV04',{first,after,staleMembershipAndRawRPCRefused:true});});
it('R9E03 a repeated editor operation after its field grant is revoked returns FORBIDDEN rather than an invalid applied ACK',async()=>{const f=await seed(),op=await rename(f);await applyEditorOperation(repository,editor,op);sql("update scenario_private.editor_scopes set revoked_at=now() where project_id='"+f.p.projectId+"' and account_id='"+editor.accountId+"';");let code='',response:unknown;try{response=await applyEditorOperation(repository,editor,op);}catch(cause){code=(cause as {code?:string}).code??String(cause);}proof('R9E03',{operation:op,response,code,expected:'FORBIDDEN'});expect(code).toBe('FORBIDDEN');expect(response).toBeUndefined();});
